#include <stdint.h>

/* Direcciones físicas = Dirección Base + Offset (RM0351) */
#define RCC_AHB2ENR_ADDR    (0x40021000UL + 0x4CUL)
#define GPIOA_MODER_ADDR    (0x48000000UL + 0x00UL)
#define GPIOA_BSRR_ADDR     (0x48000000UL + 0x18UL)

/* Punteros volátiles desreferenciados para acceso directo a registros */
#define RCC_AHB2ENR         (*(volatile uint32_t *)RCC_AHB2ENR_ADDR)
#define GPIOA_MODER         (*(volatile uint32_t *)GPIOA_MODER_ADDR)
#define GPIOA_BSRR          (*(volatile uint32_t *)GPIOA_BSRR_ADDR)

static void delay_cycles(volatile uint32_t cycles)
{
    while (cycles > 0U) {
        cycles--;
    }
}

int main(void)
{
    /* 1. Encender reloj de GPIOA en el bus AHB2 (Bit 0 = 1) */
    RCC_AHB2ENR |= (1UL << 0);

    /* 2. Configurar PA5 como salida digital: MODE5[1:0] (bits 11 y 10) = 01 */
    GPIOA_MODER &= ~(3UL << 10);   /* Limpia bits 11 y 10 -> 00 */
    GPIOA_MODER |=  (1UL << 10);   /* Pone bit 10 en 1     -> 01 */

    while (1) {
        /* 3. Encender LD2: BS5 (Bit 5 = 1) -> PA5 en 3.3V */
        GPIOA_BSRR = (1UL << 5);
        delay_cycles(400000U);

        /* 4. Apagar LD2: BR5 (Bit 21 = 1) -> PA5 en 0V */
        GPIOA_BSRR = (1UL << 21);
        delay_cycles(400000U);
    }
}
